root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='wheelHome')navigateWheel(null);if(b.hasAttribute('data-broad')&&family!==null)toggleRadialNote(broadName(families[family]),families[family].name);if(b.dataset.editNote)options.onEdit?.(b.dataset.editNote);});
mountWheel();watchLabelSize();
