return {locate(name,sense){clearTimeout(locateTimer);located={name,sense};refreshRadialStates();announce(name+' '+sense+' located on wheel.');locateTimer=setTimeout(()=>{located=null;if(root.isConnected)refreshRadialStates();},3400);},setStudy(study){root.dataset.senseStudy=String(study);refreshRadialStates();},updateNotes(notes){state.notes=Array.isArray(notes)?notes:[];refreshRadialStates();updateWheelAction();},navigate(value){navigateWheel(value===null?null:typeof value==='number'?value:families.findIndex(f=>f.name===value));},setCompact(value){compactWheel=!!value;$('#radial').classList.toggle('compact-wheel',compactWheel);labelFitCache.clear();redrawLabels();},destroy(){clearTimeout(locateTimer);cancelAnimationFrame(radialFrame);cancelAnimationFrame(sliceContentFrame);cancelAnimationFrame(labelResizeFrame);labelResizeObserver?.disconnect();clearTimeout(familyTipTimer);root.remove();}};
